import os,re,subprocess as s,sys,tempfile
def fail(m):
    print(m);sys.exit(1)
for osn in ('macos','windows','linux'):
    p=s.run([sys.executable,'_tools/install_wezterm.py','--plan','--os',osn],capture_output=True,text=True,timeout=60)
    if p.returncode!=0 or not re.search(r'https://\S+',p.stdout) or not re.search(r'\b[0-9a-f]{64}\b',p.stdout): fail('%s plan: %s %r'%(osn,p.returncode,p.stdout[:300]))
H=tempfile.mkdtemp();f=os.path.join(H,'fake.zip');open(f,'wb').write(b'not a wezterm release')
E=dict(os.environ,HOME=H,USERPROFILE=H,LOCALAPPDATA=H,XDG_DATA_HOME=H,APPDATA=H)
p=s.run([sys.executable,'_tools/install_wezterm.py','--from',f,'--yes'],capture_output=True,text=True,env=E,timeout=60)
if p.returncode==0: fail('a file whose SHA-256 is not the pin was accepted')
left=[x for x in os.listdir(H) if x!='fake.zip']
if left: fail('something was installed after the refusal: %r'%left)
print('ok: a pinned URL and SHA-256 per OS; a wrong file is refused and nothing installed')
